x-text .title-wrapper {
	min-height: 16px;
}
.products .box-text .name.product-title,
.products .box-text p.name {
	min-height: 3.6em;
	overflow: hidden;
	display: -webkit-box;
	-webkit-line-clamp: 3;
	-webkit-box-orient: vertical;
	line-height: 1.2;
	margin-bottom: 6px;
}

/* --- 5. "Neturime" badge: svelnus, sviesiai pilkas, virsuje DESINEJE --- */
.products li.product .box-image .out-of-stock-label,
.product-small .box-image .out-of-stock-label {
	position: absolute !important;
	top: 10px !important;
	right: 10px !important;
	left: auto !important;
	bottom: auto !important;
	transform: none !important;
	margin: 0 !important;
	width: auto !important;
	max-width: calc(100% - 16px) !important;
	padding: 4px 9px !important;
	font-size: 11px !important;
	font-weight: 600 !important;
	line-height: 1.3 !important;
	text-transform: none !important;        /* "Neturime", ne "NETURIME" */
	letter-spacing: 0.2px !important;
	color: #555 !important;
	background: #f2f2f2 !important;
	border: 1px solid #e2e2e2 !important;
	border-radius: 14px !important;          /* svelniai apvalus */
	z-index: 6 !important;
	white-space: nowrap !important;
	box-shadow: 0 1px 2px rgba(0,0,0,0.06) !important;
}

/* --- 6. Out-of-stock nuotrauka: blankesne (subtilu, preke matosi) --- */
.products li.product.outofstock .box-image img,
.products li.product.out-of-stock .box-image img,
.product-small.outofstock .box-image img,
.product-small.out-of-stock .box-image img {
	opacity: 0.45 !important;
	filter: grayscale(55%) !important;
}
